    {
      "name": "board",
      "url": {
        "%context%": true,
        "index": "tennis-scores*",
        "body": {
          "size": 1,
          "sort": [
            {
              "offset": {
                "order": "desc",
                "unmapped_type": "long"
              }
            }
          ],
          "_source": [
            "match_id",
            "tournament_name",
            "status",
            "set_score",
            "scores",
            "game_score",
            "server",
            "winner",
            "player_a",
            "player_b",
            "document_id",
            "offset",
            "@timestamp",
            "player_a_logo",
            "player_b_logo"
          ]
        }
      },
      "format": {
        "property": "hits.hits"
      }
    },
    {
      "name": "pred",
      "url": {
        "%context%": true,
        "index": "tennis-predictions*",
        "body": {
          "size": 100,
          "sort": [
            {
              "offset": {
                "order": "desc",
                "unmapped_type": "long"
              }
            }
          ],
          "_source": [
            "match_id",
            "document_id",
            "player_a_win_probability",
            "player_b_win_probability",
            "status",
            "player_a",
            "player_b",
            "sets_a",
            "sets_b",
            "games_a",
            "games_b",
            "score_a",
            "score_b",
            "offset",
            "timestamp"
          ]
        }
      },
      "format": {
        "property": "hits.hits"
      }
    },
    {
      "name": "history",
      "source": "pred",
      "transform": [
        {
          "type": "filter",
          "expr": "isValid(datum._source.player_a_win_probability)"
        },
        {
          "type": "collect",
          "sort": {
            "field": "_source.offset",
            "order": "ascending"
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "n"
          ]
        },
        {
          "type": "formula",
          "as": "a",
          "expr": "datum._source.player_a_win_probability"
        },
        {
          "type": "formula",
          "as": "b",
          "expr": "datum._source.player_b_win_probability"
        }
      ]
    }
  ],
  "signals": [
    {
      "name": "match",
      "update": "length(data('board')) ? data('board')[0]._source : {}"
    },
    {
      "name": "p",
      "update": "length(data('pred')) ? data('pred')[0]._source : {}"
    },
    {
      "name": "finished",
      "update": "match.status === 'Finished'"
    },
    {
      "name": "hasP",
      "update": "isValid(p.player_a_win_probability)"
    },
    {
      "name": "numSets",
      "update": "match.scores ? length(match.scores) : 0"
    },
    {
      "name": "sync",
      "update": "hasP && p.document_id === match.document_id"
    },
    {
      "name": "periods",
      "update": "match.set_score ? split(match.set_score,'-') : []"
    },
    {
      "name": "points",
      "update": "match.game_score ? split(match.game_score,'-') : []"
    }
  ],
